#include <string>

int main() {
    // Initialize shared memory
    boost::interprocess::shared_memory_object shmem(boost::interprocess::CREATE_OR_OPEN, "shared_memory", boost::interprocess::read_write);
    boost::interprocess::mapped_region region(shmem, boost::interprocess::read_write);

    // Initialize semaphore
    boost::interprocess::interprocess_semaphore semaphore(1);

    // Initialize message queue
    boost::interprocess::message_queue message_queue(boost::interprocess::CREATE_OR_OPEN, "message_queue");

    // Initialize data to be sent
    std::string data = "Hello from sender!";
    char* ptr = new char[data.size() + 1];
    ptr[data.size()] = '\0';
    std::copy(data.begin(), data.end(), ptr);

    // Write data to shared memory
    boost::interprocess::memcpy(region.get_address(), ptr, data.size());
    delete[] ptr;

    // Signal the semaphore to allow the receiver to read from shared memory
    semaphore.post();

    // Send data to the message queue
    message_queue.send(data.c_str(), data.size());

    // Wait for the receiver to receive the data
    semaphore.wait();

    // Print a success message
    std::cout << "Data sent successfully!" << std::endl;

    return 0;
}
