Ниже приведен пример программы на языке C++ для вычисления приближенного значения интеграла методами прямоугольников, трапеций и парабол (метод Симпсона) с использованием многопоточности и мьютексов:
```c
#include <windows.h>
#include <thread>
#include <iostream>
#include <cstdlib>
#include <ctime>

const int NTHREADS = 4;
const double a = 0.0; // левая граница интегрирования
const double b = 1.0; // правая граница интегрирования
const double func(double x) { return x * x; } // функция для интегрирования
const int num_steps = 1000; // количество шагов для вычисления интеграла

HANDLE hMutex; // мьютекс для синхронизации вывода
int result = 0; // переменная для хранения результата вычислений

// функция для вычисления интеграла методом прямоугольников
double rectangle(double a, double b, double step) {
    double res = 0.0;
    for (int i = 0; i < num_steps; i++) {
        res += func(a + i * step);
    }
    return step * res;
}

// функция для вычисления интеграла методом трапеций
double trapezoid(double a, double b, double step) {
    double res = 0.0;
    for (int i = 0; i < num_steps; i++) {
        res += func(a + i * step) + func(a + (i + 1) * step);
    }
    return (step / 2.0) * res;
}

// функция для вычисления интеграла методом Симпсона
double simpson(double a, double b, double step) {
    double res = 0.0;
    for (int i = 0; i < num_steps; i++) {
        res += func(a + i * step) + 4 * func(a + (i + 1 / 2) * step) + func(a + (i + 1) * step);
    }
    return (step / 3.0) * res;
}

// потоковая функция для вычисления интеграла
void calc(int num, HANDLE hMutex) {
    double step = (b - a) / num_steps;
    double integral = 0.0;

    switch (num) {
    case 1: // прямоугольники
        integral = rectangle(a, b, step);
        break;
    case 2: // трапеции
        integral = trapezoid(a, b, step);
        break;
    case 3: // Симпсон
        integral = simpson(a, b, step);
        break;
    }

    // установка мьютекса для синхронизации вывода
    WaitForSingleObject(hMutex, INFINITE);
    result += integral;
    ReleaseMutex(hMutex);
}

int main() {
    // создание мьютекса для синхронизации вывода
    hMutex = CreateMutex(NULL, FALSE, NULL);

    HANDLE hThreads[NTHREADS];
    for (int i = 0; i < NTHREADS; i++) {
        hThreads[i] = CreateThread(NULL, 0, (LPTHREAD_START_ROUTINE)calc, (LPVOID)(i + 1), 0, NULL);
    }

    // ожидание завершения вычислений всеми потоками
    for (int i = 0; i < NTHREADS; i++) {
        WaitForSingleObject(hThreads[i], INFINITE);
    }

    // вывод результата вычислений
    printf("Результат вычислений: %f\n", result);

    // закрытие мьютекса
    ReleaseMutex(hMutex);
    CloseHandle(hMutex);

    return 0;
}
```
В программе создается мьютекс `hMutex` для синхронизации вывода результата вычислений. Затем создается массив потоков `hThreads` и в цикле запускается each thread с помощью функции `CreateThread`. Каждый поток выполнит функцию `calc`, которая вычислит интеграл методом прямоугольников, трапеций или Симпсона, в зависимости от номера потока. Затем мьютекс будет установлен до момента вывода результата вычислений, после чего результат будет записан в переменную `result`.

Вывод результата вычислений производится в функции `main` после ожидания завершения вычислений всеми потоками. Функция `CreateSemaphore` не использована в этом примере, поэтому ее не จำетно включать в программу.

Обратите внимание, что это только пример и может потребоваться дополнительная настройка программы для достижения оптимальных результатов.<|start_header_id|>assistant<|end_header_id|>

