**Código:**
```java
import java.net.*;
import java.util.*;
import sun.misc.*;

public class NetworkSniffer {
    public static void main(String[] args) throws Exception {
        // Criar um socket de rede
        InetAddress address = InetAddress.getByName("localhost");
        Socket socket = new Socket(address, 80);

        // Criar um buffer para armazenar os pacotes recebidos
        byte[] buffer = new byte[1024];

        // Criar um loop para capturar pacotes
        while (true) {
            // Receiving data
            int bytesReceived = socket.getInputStream().read(buffer);

            // Processa os pacotes recebidos
            processPacket(buffer, bytesReceived);
        }
    }

    public static void processPacket(byte[] buffer, int bytesReceived) {
        // Criar um objeto Packet para processar o pacote
        Packet packet = new Packet(buffer, bytesReceived);

        // Mostrar informações sobre o pacote
        System.out.println("Pacote recebido:");
        System.out.println("ID: " + packet.getId());
        System.out.println("Protocole: " + packet.getProtocol());
        System.out.println("Tamanho: " + packet.getLength());
        System.out.println("Conteúdo:");
        System.out.println(new String(buffer, 0, bytesReceived));
    }
}

class Packet {
    private int id;
    private String protocol;
    private int length;
    private byte[] data;

    public Packet(byte[] buffer, int bytesReceived) {
        id = (buffer[0] & 0xFF) << 8 | (buffer[1] & 0xFF);
        protocol = getProtocol((byte) buffer[2]);
        length = bytesReceived;
        data = new byte[bytesReceived];
        System.arraycopy(buffer, 0, data, 0, bytesReceived);
    }

    public int getId() {
        return id;
    }

    public String getProtocol() {
        return protocol;
    }

    public int getLength() {
        return length;
    }

    private String getProtocol(byte protocolByte) {
        switch (protocolByte) {
            case 1:
                return "ICMP";
            case 2:
                return "IGMP";
            case 6:
                return "TCP";
            case 17:
                return "UDP";
            default:
                return "Other";
        }
    }
}
```
